import json

# Get CVSS from trivy output (which uses NVD/RedHat CVSS)
data = json.load(open('/root/trivy_output.json'))
results = data.get('Results', [])
trivy_cvss = {}
for r in results:
    for v in r.get('Vulnerabilities', []):
        vid = v.get('VulnerabilityID', '')
        cvss = v.get('CVSS', {})
        scores = {}
        for src, val in cvss.items():
            s = val.get('V3Score', '')
            if s:
                scores[src] = s
        trivy_cvss[vid] = scores

for vid, scores in trivy_cvss.items():
    print(f"{vid}: {scores}")
